// Find tasks containing @CG with proper validation
const tasks = $input.first().json.result || [];
console.log(`Checking ${tasks.length} tasks for @CG mentions`);

// Look for tasks with "@CG" in title, description, or comments
const matchingTasks = [];

for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Check if it's an @CG task (case insensitive)
  if (title.toLowerCase().includes('@cg') || 
      description.toLowerCase().includes('@cg')) {

    const taskDetails = {
      task_id: task.id,
      title: title.trim(),
      description: description.trim(),
      project_id: task.project_id || 1,
      attachments: task.attachments || [],
      match_location: [],
      // Extract company name from title (everything before @CG)
      company_name: title.split('@CG')[0].trim() || 'Unknown Company'
    };

    // Record where the match was found
    if (title.toLowerCase().includes('@cg')) {
      taskDetails.match_location.push('title');
    }
    if (description.toLowerCase().includes('@cg')) {
      taskDetails.match_location.push('description');
    }

    console.log(`✅ Found @CG task: "${title}" (ID: ${task.id})`);
    console.log(`Company: ${taskDetails.company_name}`);
    console.log(`Match found in: ${taskDetails.match_location.join(', ')}`);

    matchingTasks.push(taskDetails);
  }
}

if (matchingTasks.length > 0) {
  return matchingTasks.map(task => ({ json: task }));
}

// If no tasks found, stop gracefully
console.log('ℹ️ No @CG tasks found');
throw new Error('No @CG tasks found');

